// The report: every failure is kept with its input, and the test fails with the first few of each family.
type Rep = { name: string; total: number; fails: Map<string, string[]> };
const rep = (name: string): Rep => ({ name, total: 0, fails: new Map() });
const fail = (r: Rep, family: string, why: string) => { if (!r.fails.has(family)) r.fails.set(family, []); r.fails.get(family)!.push(why); };
function done(r: Rep) {
  const n = [...r.fails.values()].reduce((a, b) => a + b.length, 0);
  const lines = [`[adversarial-r2] ${r.name}: ${r.total} cases, ${n} failures`];
  for (const [k, xs] of r.fails) { lines.push(`  FAIL ${k}: ${xs.length}`); for (const x of xs.slice(0, 3)) lines.push(`    ${x.slice(0, 400)}`); }
  console.log(lines.join("\n"));
  eq(n, 0, `${r.name}: ${n} failures (see the report above)`);
}
const all = (n: number) => Array.from({ length: n }, (_, i) => i + 1);
const sorted = (xs: number[]) => [...xs].sort((a, b) => a - b);
const isAll = (xs: number[], n: number) => JSON.stringify(sorted(xs)) === JSON.stringify(all(n));

// ------------------------------------------------------------------------------------------------ the approval paths
async function cardPath(texts: string[], o: { change?: number; at?: number; thread?: string } = {}): Promise<number[]> {
  const d = cardDb({ n: N });
  const shown = await d.say("show my applications", { at: T0 });
  if (shown?.status !== "shown") throw new Error(`card not shown: ${shown?.reply}`);
  if (o.change) d.change(o.change);
  for (const t of texts) {
    if (o.thread && o.thread !== "TH") {
      // Another chat of the same person: the store answers for the chat that showed the card only.
      const store = { ...d.store, lastAssistantIntent: async (th: string) => th === "TH" ? await d.store.lastAssistantIntent(th) : null, lastShownCard: async (th: string) => th === "TH" ? await d.store.lastShownCard(th) : null };
      await cardTurn({ message: t, userId: "TEST-USER", threadId: o.thread, now: o.at ?? T0 + 60_000, store });
    } else await d.say(t, { at: o.at ?? T0 + 60_000 });
  }
  const card = d.cards[0];
  for (const q of d.queue) if (q.approval !== card.items.find((i) => i.prepared_id === q.prepared_id)!.payload_hash) throw new Error("queued under another hash");
  return d.queue.map((q) => card.items.find((i) => i.prepared_id === q.prepared_id)!.n);
}
async function outreachBatch(store: ReturnType<typeof memoryOutreachStore>, user: string, thread: string) {
  const ds: any[] = [];
  for (let i = 1; i <= N; i++) {
    const d: any = { n: i, recipient: { name: `Person ${i} Synthetic`, firm: "Firm", title: "Analyst", school: "", email: `p${i}@firm.example`, source: `list.csv, row ${i}` },
      subject: `Question ${i}`, body: `Hi ${i}, a short synthetic note.`, footer: `Sam\n\n${OPT_OUT_LINE}`, status: "shown", approved_hash: null, approved_at: null, sent_at: null, gmail_id: null,
      gmail_thread: null, result: null, created_at: new Date(T0).toISOString(), hash: "", shared: [] };
    d.hash = await payloadHash(messageOf(d));
    ds.push(d);
  }
  await store.saveBatch(user, thread, ds, T0);
  store.setIntent(thread, OUTREACH_INTENT);
}
async function outreachPath(texts: string[], o: { thread?: string; user?: string; change?: number; at?: number } = {}): Promise<number[]> {
  const store = memoryOutreachStore();
  await outreachBatch(store, "U", "TH");
  if (o.change) {
    const d = (await store.latestBatch("U")).find((x) => x.n === o.change)!;
    await store.update("U", { ...d, body: `${d.body} (changed after it was shown)` }, { status: "shown" });
  }
  for (const t of texts) await outreachTurn({ message: t, userId: o.user ?? "U", threadId: o.thread ?? "TH", now: o.at ?? T0 + 60_000, store, gmailConnected: async () => true });
  const approved = (await store.latestBatch("U")).filter((d) => d.status === "approved");
  for (const d of approved) if (d.approved_hash !== d.hash || d.hash !== await payloadHash(messageOf(d))) throw new Error("approved under another hash");
  return approved.map((d) => d.n);
}
async function repliesPath(texts: string[], o: { thread?: string; user?: string } = {}): Promise<number[]> {
  const store = memoryRepliesStore();
  const items = [];
  for (let i = 1; i <= N; i++) {
    const payload = { to: `c${i}@beta.example`, subject: `Re: note ${i}`, text: `Following up ${i}.` };
    items.push({ thread_id: `T${i}`, kind: "followup" as const, payload, hash: await actionHash("followup", payload), step: 1 });
  }
  await store.saveActions("U", items, T0);
  store.setIntent("CH", ACTIONS_INTENT);
  for (const t of texts) await repliesTurn({ message: t, userId: o.user ?? "U", chatThreadId: o.thread ?? "CH", now: T0 + 60_000, store, tz: "America/Chicago" });
  return store.dump().actions.filter((a: any) => a.status === "approved" && a.user_id === "U").map((a: any) => a.n);
}
async function billingPath(texts: string[], o: { thread?: string } = {}): Promise<number[]> {
  const sub: Subscription = { status: "active", plan: "monthly", price_cents: 1000, current_period_start: "2026-10-27T15:00:00.000Z", current_period_end: "2026-11-27T15:00:00.000Z",
    stripe_customer_id: "cus_fake1", stripe_subscription_id: "sub_fake1", cancel_at_period_end: false };
  const last: Record<string, Record<string, unknown> | null> = {};
  const cancels: string[] = [];
  const store: BillingStore = { subscription: async () => sub, lastMeta: async (th: string) => last[th] ?? null, markCancelling: async () => {} } as any;
  const stripe = { async cancelAtPeriodEnd(id: string) { cancels.push(id); return { cancel_at_period_end: true, cancel_at: 1, current_period_end: 1 }; }, async listInvoices() { return []; } };
  const say = async (message: string, th: string) => { const r = await billingTurn({ message, userId: "u1", threadId: th, now: T0, store, stripe }); last[th] = r ? { intent: r.intent, ...(r.meta ?? {}) } : null; return r; };
  const ask = await say("cancel my plan", "t1");
  if (!ask || !/Reply "yes" to cancel/.test(ask.reply)) throw new Error(`cancel not asked: ${ask?.reply}`);
  for (const t of texts) await say(t, o.thread ?? "t1");
  return cancels.length ? [1] : [];
}
// The brain's confirm_profile_fact after the fact was shown in the reply before (the strongest case for a yes).
