    last = OUTREACH_INTENT; // the drafts were shown after the card
    const cstore = { ...d.store, lastAssistantIntent: async () => last, lastShownCard: async () => (last === CARD_INTENT ? d.cards[0].id : null) };
    const cardAns = await cardTurn({ message: y, userId: "TEST-USER", threadId: "TH", now: T0 + 60_000, store: cstore });
    if (!cardAns) await outreachTurn({ message: y, userId: "U", threadId: "TH", now: T0 + 60_000, store: ostore, gmailConnected: async () => true });
    const queued = d.queue.length, approved = (await ostore.latestBatch("U")).filter((x) => x.status === "approved").length;
    if (queued) fail(r, "two_batches", `${JSON.stringify(y)}: the card (not the last word) was approved: ${queued}`);
